// Weekly client reports, built here and generated by Gamma.
//
// Why this lives in the backend rather than being made by hand: a report that someone has to
// remember to run is a report that stops happening in week three. This runs on the same schedule
// as the syncs, off the same stored rows the dashboard reads, so the deck and the dashboard
// cannot disagree. That matters more than it sounds: the whole point of the desk is that one
// number means one thing everywhere.
//
// Needs GAMMA_API_KEY in the environment. Without it the mode logs and does nothing, rather
// than failing the run.
//
// Cost note: each deck spends Gamma credits from the workspace's own balance. Nothing new is
// billed, but the balance is finite, so clients with no spend in the week are skipped.

import { addDays, log, nowIso, round, todayStr } from './util.js';

const API = 'https://public-api.gamma.app/v1.0/generations';
const KEY = () => process.env.GAMMA_API_KEY || '';

const money = (v, cur) => {
  const s = { INR: '₹', USD: '$', AED: 'AED ', GBP: '£', EUR: '€' }[cur] || (cur + ' ');
  const n = Math.round(Math.abs(v));
  return s + (cur === 'INR' ? n.toLocaleString('en-IN') : n.toLocaleString('en-US'));
};
const pct = (a, b) => (b ? `${a - b >= 0 ? 'up' : 'down'} ${Math.abs((a - b) / b * 100).toFixed(0)} percent` : 'no comparison available');
const dmy = (s) => {
  const M = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  return `${+s.slice(8, 10)} ${M[+s.slice(5, 7) - 1]} ${s.slice(0, 4)}`;
};

// The week being reported: the seven complete days ending yesterday, and the seven before it.
export function weekWindow(today = todayStr()) {
  const end = addDays(today, -1);
  const start = addDays(end, -6);
  return { start, end, pStart: addDays(start, -7), pEnd: addDays(start, -1) };
}

const FIELDS = ['spend','impressions','clicks','purchases','revenue','leads','orders','netSales','refunds','units','newCustomerOrders',
                'srcMeta','srcGoogle','srcDirect','srcOther','srcUnknown','srcNone'];
function sumRows(rows, lo, hi) {
  const o = Object.fromEntries(FIELDS.map((k) => [k, 0]));
  o.hasShop = false;
  for (const r of rows) {
    if (r.date < lo || r.date > hi) continue;
    if (r.platform === 'shopify') o.hasShop = true;
    for (const k of FIELDS) o[k] += r[k] || 0;
  }
  o.sales = o.hasShop ? o.orders : o.purchases;
  o.money = o.hasShop ? o.netSales : o.revenue;
  o.mer = o.spend ? o.money / o.spend : 0;
  o.aov = o.sales ? o.money / o.sales : 0;
  o.cpa = o.sales ? o.spend / o.sales : 0;
  o.cpl = o.leads ? o.spend / o.leads : 0;
  return o;
}

// The deck's text. Written as finished prose with explicit breaks rather than as a prompt,
// because a prompt would let the model restate the numbers in its own words, and a number
// restated is a number that can drift. textMode preserve plus inputTextBreaks keeps what is
// written here exactly as written.
export function reportText(c, A, P, w) {
  const cur = c.currency || 'INR';
  const isE = c.type !== 'lead';
  const B = [];
  const name = c.name;

  B.push(`Slide 1, title card: ${name}. Weekly Performance Report. ${dmy(w.start)} to ${dmy(w.end)}. Prepared by Per4mance Guru.`);

  if (isE) {
    B.push(`Slide 2, The headline: ${A.hasShop ? 'Net sales' : 'Revenue'} reached ${money(A.money, cur)} this week, ${pct(A.money, P.money)} on the week before. Ad spend was ${money(A.spend, cur)}, ${pct(A.spend, P.spend)}. That works out to ${A.mer.toFixed(2)} times back for every rupee spent, against ${P.mer.toFixed(2)} the week before. Put plainly, every ${money(100, cur)} of advertising returned ${money(A.mer * 100, cur)}.`);
    B.push(`Slide 3, The week in numbers. Present as a comparison table with three columns: Metric, This week, Last week.
Ad spend: ${money(A.spend, cur)} against ${money(P.spend, cur)}.
${A.hasShop ? 'Net sales' : 'Revenue'}: ${money(A.money, cur)} against ${money(P.money, cur)}.
Orders: ${A.sales} against ${P.sales}.
Average order value: ${money(A.aov, cur)} against ${money(P.aov, cur)}.
Cost per order: ${money(A.cpa, cur)} against ${money(P.cpa, cur)}.
Units sold: ${A.units} against ${P.units}.
First-time buyers: ${A.newCustomerOrders} against ${P.newCustomerOrders}.
Returns: ${money(A.refunds, cur)} against ${money(P.refunds, cur)}.`);
  } else {
    B.push(`Slide 2, The headline: ${A.leads} enquiries came in this week, ${pct(A.leads, P.leads)} on the week before, at ${money(A.cpl, cur)} each against ${money(P.cpl, cur)}. Ad spend was ${money(A.spend, cur)}, ${pct(A.spend, P.spend)}.`);
    B.push(`Slide 3, The week in numbers. Present as a comparison table with three columns: Metric, This week, Last week.
Ad spend: ${money(A.spend, cur)} against ${money(P.spend, cur)}.
Enquiries: ${A.leads} against ${P.leads}.
Cost per enquiry: ${money(A.cpl, cur)} against ${money(P.cpl, cur)}.
Clicks to site: ${A.clicks} against ${P.clicks}.
Times the ads were seen: ${A.impressions} against ${P.impressions}.`);
  }

  // The honest slide. It exists because a client who adds Meta's revenue to Google's revenue
  // walks away believing they earned roughly twice what they earned.
  if (isE && A.hasShop) {
    const claimed = Math.round(A.purchases);
    const real = Math.round(A.orders);
    const src = (A.srcMeta || A.srcGoogle)
      ? ` Your store's own records show ${Math.round(A.srcMeta)} of this week's orders arrived from Instagram or Facebook, and ${Math.round(A.srcGoogle)} from Google.`
      : '';
    B.push(`Slide 4, A note on how sales are counted: The advertising platforms together report ${claimed} purchases for this week. Your store recorded ${real} orders. These two numbers answer different questions. The platforms count people who saw an ad and later bought, inside their own attribution window, and when someone sees an ad on more than one platform before buying, each one counts that order as its own.${src} Every figure in this report is taken from your store rather than from what the platforms claim, which is why the numbers here match your Shopify admin exactly.`);
  }

  if (isE && A.refunds > 0 && A.money > 0) {
    const rate = A.refunds / (A.money + A.refunds) * 100;
    B.push(`Slide 5, One number to watch: Returns took ${money(A.refunds, cur)} out of the week, roughly ${rate.toFixed(1)} percent of what was sold. The net sales figure above already has this removed, so nothing in this report is overstated. It is flagged here because it is the quietest way for a good week to turn into an average one, and it is worth a look at product level.`);
  }

  B.push(`Slide 6, Where this leaves us: ${
    isE
      ? (A.mer >= P.mer && A.spend > P.spend
          ? 'Spend rose and efficiency improved at the same time, which usually means there is room to push further before the account resists.'
          : A.mer < P.mer && A.spend > P.spend
            ? 'Spend rose while the return per rupee fell, so the next move is to find where the extra budget went rather than simply adding more.'
            : 'The week held its shape. The work from here is on what each creative and campaign contributes rather than on the overall budget.')
      : (A.cpl && P.cpl && A.cpl <= P.cpl
          ? 'Cost per enquiry improved this week, which usually means there is room to add budget before it climbs again.'
          : 'Cost per enquiry moved against us this week, so the next step is to look at which campaigns carried the rise.')
  } We will bring the detail behind these numbers to the next review.`);

  return B.join('\n\n---\n\n');
}

async function post(url, body, method = 'POST') {
  const r = await fetch(url, {
    method,
    headers: { 'X-API-KEY': KEY(), 'Content-Type': 'application/json', Accept: 'application/json' },
    ...(body ? { body: JSON.stringify(body) } : {}),
  });
  const text = await r.text();
  let j; try { j = JSON.parse(text); } catch { j = { raw: text }; }
  if (!r.ok) throw new Error(`gamma ${r.status}: ${(j.message || j.error || text || '').toString().slice(0, 200)}`);
  return j;
}

// Gamma generates asynchronously, so the id comes back first and the url follows. Polled rather
// than waited on in one call, with a ceiling so a stuck generation cannot hold the whole run.
async function waitForUrl(generationId, { tries = 40, gapMs = 6000 } = {}) {
  for (let i = 0; i < tries; i++) {
    await new Promise((res) => setTimeout(res, gapMs));
    const s = await post(`${API}/${encodeURIComponent(generationId)}`, null, 'GET');
    if (s.status === 'completed' && s.gammaUrl) return s.gammaUrl;
    if (s.status === 'failed') throw new Error(`gamma generation failed: ${s.error || 'no reason given'}`);
  }
  throw new Error('gamma generation still pending after the wait ceiling');
}

export async function weeklyReports(store, clients, opts = {}) {
  if (!KEY()) { log('gamma: GAMMA_API_KEY is not set, skipping weekly reports'); return { made: 0, skipped: clients.length }; }
  const w = weekWindow(opts.today || todayStr());
  // One client at a time when asked. Each deck spends credits from a finite balance, so a run
  // that quietly bills for thirty of them is not something to trigger by accident.
  const only = String(opts.only || '').trim().toLowerCase();
  const list = only ? clients.filter((c) => c.id === only) : clients;
  if (only && !list.length) { log(`gamma: no client with id "${only}"`); return { made: 0, skipped: 0, failed: 0 }; }
  let made = 0, skipped = 0, failed = 0;

  for (const c of list) {
    const id = `${c.id}_${w.end}`;
    if (!opts.force && (await store.get('weekly', id))) { skipped++; continue; }   // already made this week

    const rows = await store.list('daily', [['clientId', '==', c.id]]);
    const A = sumRows(rows, w.start, w.end);
    const P = sumRows(rows, w.pStart, w.pEnd);
    // No spend and no sales means there is nothing to report, and a deck costs credits.
    if (!A.spend && !A.money && !A.leads) { skipped++; continue; }

    try {
      const body = {
        inputText: reportText(c, A, P, w),
        format: 'presentation',
        textMode: 'preserve',          // keeps the numbers exactly as written above
        cardSplit: 'inputTextBreaks',
        title: `${c.name} Weekly Report, ${dmy(w.start)} to ${dmy(w.end)}`,
        imageOptions: { source: 'noImages' },
        textOptions: { language: 'en-in' },
        ...(process.env.GAMMA_THEME_ID ? { themeId: process.env.GAMMA_THEME_ID } : {}),
      };
      const gen = await post(API, body);
      const url = await waitForUrl(gen.generationId);
      await store.set('weekly', id, {
        clientId: c.id, name: c.name, weekStart: w.start, weekEnd: w.end,
        gammaUrl: url, generatedAt: nowIso(),
        spend: round(A.spend), sales: A.sales, money: round(A.money),
        mer: round(A.mer, 2), currency: c.currency || 'INR',
      });
      made++;
      log(`gamma: ${c.id} weekly report ready (${w.start} to ${w.end})`);
    } catch (e) {
      failed++;
      log(`gamma: ${c.id} weekly report FAILED (${String(e.message || e).slice(0, 160)})`);
    }
  }
  log(`gamma: ${made} report${made === 1 ? '' : 's'} made, ${skipped} skipped, ${failed} failed, week ${w.start} to ${w.end}`);
  return { made, skipped, failed, week: w };
}
